-- Curated Yozgat destinations: official/public tourism sources; safe to re-run.
with seed(name, category, place_type, city, address, latitude, longitude, slug, short_description, long_description, source_url, external_source, verified, trust_score, is_active, content_review_status, tags) as (
 values
 ('Sarıkaya Roma Hamamı (Bazilika Therma)', 'history', 'archaeological_site', 'Yozgat', 'Kaplıca Mahallesi, Sarıkaya, Yozgat', 39.4930, 35.3760, 'yozgat-sarikaya-roma-hamami', 'Roma döneminden kalan, sıcak su kaynağı çevresinde gelişmiş anıtsal hamam kalıntısı.', 'Aquae Sarvenae ve Therma Basilica adlarıyla bilinen yerleşimdeki hamam, Anadolu’daki Roma dönemi termal yapılarının önemli örneklerindendir. Ziyaret öncesi güncel erişim durumunu kontrol edin.', 'https://muze.gov.tr/muze-detay?DistId=MRK&SectionId=RMH01', 'curated_seed', true, 90, true, 'source_backed', jsonb_build_array('arkeoloji','Roma dönemi','Yozgat')),
 ('Kerkenes Harabeleri', 'history', 'archaeological_site', 'Yozgat', 'Şahmuratlı köyü çevresi, Sorgun, Yozgat', 39.6500, 35.0800, 'yozgat-kerkenes-harabeleri', 'Demir Çağı yerleşimiyle tanınan, Kerkenes Dağı çevresindeki geniş arkeolojik alan.', 'Kerkenes, Yozgat’ın önemli arkeolojik alanlarından biridir. Araştırmalar yerleşimin tarihine ilişkin farklı bulgular ortaya koymuştur; alanı ziyaret ederken koruma sınırlarına uyulmalıdır.', 'https://goturkiye.com/tr/yozgat/yozgatta-yapmadan-donme', 'curated_seed', true, 88, true, 'source_backed', jsonb_build_array('arkeoloji','Demir Çağı','Yozgat')),
 ('Kazankaya Kanyonu', 'nature', 'canyon', 'Yozgat', 'Kazankaya, Aydıncık, Yozgat', 40.1300, 35.2900, 'yozgat-kazankaya-kanyonu', 'Aydıncık yakınlarında, yürüyüş ve doğa gözlemiyle öne çıkan uzun kanyon vadisi.', 'Kazankaya’dan başlayan kanyon, doğal kaya oluşumları ve yaban hayatıyla tanınır. Arazi koşulları değişebildiğinden yürüyüş öncesinde hava ve erişim koşullarını kontrol edin.', 'https://yozgat.meb.gov.tr/www/ilimiz-hakkinda-turizm/icerik/2355', 'curated_seed', true, 88, true, 'source_backed', jsonb_build_array('kanyon','doğa','Yozgat'))
)
insert into public.places (name, category, place_type, city, address, latitude, longitude, slug, short_description, long_description, source_url, external_source, verified, trust_score, is_active, content_review_status, tags)
select s.* from seed s
where not exists (select 1 from public.places p where p.slug = s.slug)
  and not exists (select 1 from public.places p where p.city = s.city and lower(trim(p.name)) = lower(trim(s.name)));
